"""The referent framings a question set can carry, in reading order.

`make_framings.py` produces exactly these three for every source question; `report.py`
groups and pairs on them. Rows that never went through stage 0 carry UNSPECIFIED, so a
raw question set still reports a single overall score.
"""

# Generated by make_framings.py, one row each per source question.
FRAMINGS = ("generic", "named", "second_person")

# Fallback for rows with no `framing` field, e.g. a question set pulled straight from
# the Hub and fed to generate_responses.py without a stage-0 pass.
UNSPECIFIED = "unspecified"

# Display/grouping order; anything else is appended alphabetically.
FRAMING_ORDER = [*FRAMINGS, UNSPECIFIED]
